import os, json, glob
import numpy as np

def _safe_mean(xs, axis=None):
    xs = np.asarray(xs, dtype=float)
    return float(np.mean(xs, axis=axis))

def _find_len32_sequence(obj):
    # Recursively search for a length-32 numeric sequence in nested dict/list
    if isinstance(obj, dict):
        for v in obj.values():
            out = _find_len32_sequence(v)
            if out is not None:
                return out
    elif isinstance(obj, (list, tuple)):
        # If it's exactly a list of 32 scalars, return it
        if len(obj) == 32 and all(isinstance(x, (int, float)) for x in obj):
            return list(map(float, obj))
        # Else search elements
        for v in obj:
            out = _find_len32_sequence(v)
            if out is not None:
                return out
    return None

def _load_gamma_vectors(path_pat):
    gammas = []
    for p in sorted(glob.glob(path_pat)):
        try:
            with open(p, 'r') as f:
                data = json.load(f)
            g = None
            # Heuristic key tries
            for k in ['gamma', 'gamma_t', 'gamma_values', 'gamma_list']:
                if k in data and isinstance(data[k], (list, tuple)) and len(data[k]) == 32:
                    g = list(map(float, data[k]))
                    break
            if g is None:
                g = _find_len32_sequence(data)
            if g is not None and len(g) == 32:
                gammas.append(np.array(g, dtype=float))
        except Exception as e:
            print(f"[warn] Failed to parse gamma file {p}: {e}")
    return gammas

def _load_per_condition_step_mae(path_pat):
    # Expect dict[condition] -> list[32] or a nested map containing such
    step_lists = []
    for p in sorted(glob.glob(path_pat)):
        try:
            with open(p, 'r') as f:
                data = json.load(f)
            candidates = []
            # Search for dict of lists-of-32
            stack = [data]
            while stack:
                obj = stack.pop()
                if isinstance(obj, dict):
                    # If values are all lists of len 32, collect them
                    vals = list(obj.values())
                    if vals and all(isinstance(v, (list, tuple)) and len(v) == 32 for v in vals):
                        # collect
                        for v in vals:
                            candidates.append(np.array(list(map(float, v))))
                    else:
                        stack.extend(vals)
                elif isinstance(obj, list):
                    stack.extend(obj)
            if candidates:
                # average across conditions within this file -> [32]
                step_lists.append(np.mean(np.stack(candidates, axis=0), axis=0))
            else:
                # fallback: try to find a single len-32 sequence and treat it as overall step MAE
                seq = _find_len32_sequence(data)
                if seq is not None:
                    step_lists.append(np.array(seq, dtype=float))
        except Exception as e:
            print(f"[warn] Failed to parse per-condition file {p}: {e}")
    return step_lists

def test():
    os.makedirs("storage/ariadne/analyses", exist_ok=True)
    gamma_files = "storage/ariadne/analyses/fourier_learn_gamma_export_v2/*.json"
    cond_files  = "storage/ariadne/analyses/fourier_learn_gamma_per_condition/*.json"

    gammas = _load_gamma_vectors(gamma_files)
    step_mae_lists = _load_per_condition_step_mae(cond_files)

    report = []
    report.append("# γ[t]–Difficulty Alignment (Ariadne II analysis)")
    report.append("")
    report.append(f"Gamma files parsed: {len(gammas)}")
    report.append(f"Per-condition files parsed: {len(step_mae_lists)}")

    if gammas:
        g_mean = np.mean(np.stack(gammas, axis=0), axis=0)  # [32]
        report.append("gamma_mean (first 8 steps): " + ", ".join(f"{x:.3f}" for x in g_mean[:8]))
        report.append("gamma_mean (last 8 steps):  " + ", ".join(f"{x:.3f}" for x in g_mean[-8:] ))
    else:
        g_mean = None
        report.append("No gamma files found.")

    if step_mae_lists:
        mae_mean = np.mean(np.stack(step_mae_lists, axis=0), axis=0)  # [32]
        report.append("step_MAE_mean (first 8): " + ", ".join(f"{x:.5f}" for x in mae_mean[:8]))
        report.append("step_MAE_mean (last 8):  " + ", ".join(f"{x:.5f}" for x in mae_mean[-8:]))
    else:
        mae_mean = None
        report.append("No per-condition step-MAE files found.")

    if g_mean is not None and mae_mean is not None and len(g_mean) == len(mae_mean) == 32:
        corr = np.corrcoef(g_mean, mae_mean)[0,1]
        report.append(f"corr(gamma_mean, step_MAE_mean) = {corr:.4f}")
        report.append(f"alignment_score = {-corr:.4f}  # more negative means better alignment (γ high where MAE high)")
    else:
        report.append("Correlation not computed (missing data).")

    # Optional: simple condition contrast if individual condition arrays are present
    # We heuristically estimate late-horizon difficulty by averaging steps 24–32 if available
    if step_mae_lists:
        late = np.mean(np.stack(step_mae_lists, axis=0)[:, 23:], axis=(0,1))
        early = np.mean(np.stack(step_mae_lists, axis=0)[:, :4], axis=(0,1))
        report.append(f"Mean early-step MAE (~t1–t4): {early:.5f}")
        report.append(f"Mean late-step MAE (~t24–t32): {late:.5f}")

    text = "\n".join(report) + "\n"
    out_path = "storage/ariadne/analyses/ariadne2_cond_gamma_report.md"
    with open(out_path, "w") as f:
        f.write(text)
    print(text)
    print(f"[saved] {out_path}")
    return "Analysis complete"
